// A 1D cable of cardiac cells: the diffusion of the membrane potential between neighbouring
// cells, and the stimulus that starts a wave at one end. Used by main.cu, together with the
// cell model generated by `gotranx ode2cuda` (tor_ord.cuh).
#pragma once
#include <cstdint>

namespace cable
{
constexpr double dt = 0.01;  // ms, time step of both the cell model and the diffusion
constexpr double dx = 0.1;   // mm, distance between neighbouring cells
constexpr double D = 0.1;    // mm^2/ms, diffusion coefficient of the potential
constexpr double alpha = D * dt / (dx * dx);  // must be below 0.5 for stability

// The first cells are stimulated for the first millisecond, at the rate the model's own
// stimulus would raise the potential (its amplitude is -53 uA/uF, i.e. +53 mV/ms)
constexpr int n_stimulated = 5;
constexpr double stimulus_duration = 1.0;  // ms
constexpr double stimulus_rate = 53.0;     // mV/ms

// The increase of the potential of the stimulated cells in the step that starts at t
inline double stimulus(double t)
{
    return t < stimulus_duration ? stimulus_rate * dt : 0.0;
}

// One explicit step of dv/dt = D d^2v/dx^2 with no flux through the ends, from v into
// v_new, plus `stimulus` on the first n_stimulated cells. One thread per cell; v is the row
// of the potential in the state-major states, &states[v_index * n_cells].
static __global__ void diffuse(const double *v, double *v_new, const std::int64_t n_cells,
                        const double stimulus)
{
    const std::int64_t cell = static_cast<std::int64_t>(blockIdx.x) * blockDim.x + threadIdx.x;
    if (cell >= n_cells) return;

    // At the ends, the missing neighbour mirrors the existing one (no flux)
    const double left = cell > 0 ? v[cell - 1] : v[cell + 1];
    const double right = cell < n_cells - 1 ? v[cell + 1] : v[cell - 1];
    v_new[cell] = v[cell] + alpha * (left - 2.0 * v[cell] + right);
    if (cell < n_stimulated) v_new[cell] += stimulus;
}
}  // namespace cable
